 if(get_option('bhc_catalog_image_exact_batch_v170')||!function_exists('wc_get_product_id_by_sku'))return;require_once ABSPATH.'wp-admin/includes/image.php';$rows=[['sku'=>'BHC-PAKSHOMA-S9W','src'=>'pakshoma-s9w-source.png','rel'=>'bhc-image-references/pakshoma-s9w.png','title'=>'Pakshoma S9W اختصاصی 4K شفاف','ref'=>'https://pakshoma.d-km.com/en/product/9-kg-washing-machine/'],['sku'=>'BHC-SAMSUNG-QA55Q70','src'=>'samsung-qa55q70-source.png','rel'=>'bhc-image-references/samsung-qa55q70.png','title'=>'Samsung QA55Q70CAWXXY اختصاصی 4K شفاف','ref'=>'https://images.samsung.com/is/content/samsung/assets/au/tvs/product-specs/120523_Q70C-Spec-Sheet.pdf'],['sku'=>'SNOWA-S2DI-S110-W','src'=>'snowa-s2di-s110w-source.png','rel'=>'bhc-image-references/snowa-s2di-s110w.png','title'=>'Snowa S2DI-S110-W اختصاصی 4K شفاف','ref'=>'https://snowa.ir/product/s2di-s110-w/'],['sku'=>'SNOWA-SNW-9050','src'=>'snowa-snw-9050-source.png','rel'=>'bhc-image-references/snowa-snw-9050.png','title'=>'Snowa SNW-9050 اختصاصی 4K شفاف','ref'=>'https://snowa.ir/product/snw-9050/']];$processed=0;$attached=0;foreach($rows as $r){$id=wc_get_product_id_by_sku($r['sku']);$src=__DIR__.'/'.$r['src'];$file=ABSPATH.'wp-content/uploads/'.$r['rel'];if(!$id||!is_readable($src))continue;$processed++;wp_mkdir_p(dirname($file));$im=@imagecreatefrompng($src);if(!$im)continue;$w=imagesx($im);$h=imagesy($im);$scale=4096/max($w,$h);$nw=max(1,(int)round($w*$scale));$nh=max(1,(int)round($h*$scale));$out=imagecreatetruecolor($nw,$nh);imagealphablending($out,false);imagesavealpha($out,true);$t=imagecolorallocatealpha($out,0,0,0,127);imagefill($out,0,0,$t);imagecopyresampled($out,$im,0,0,0,0,$nw,$nh,$w,$h);imagepng($out,$file,6);imagedestroy($out);imagedestroy($im);$aid=get_post_thumbnail_id($id);if(!$aid||get_post_meta($aid,'_wp_attached_file',true)!==$r['rel']){$aid=wp_insert_attachment(['post_mime_type'=>'image/png','post_title'=>$r['title'],'post_status'=>'inherit','post_parent'=>$id],$file,$id);if($aid&&!is_wp_error($aid